/// What the route of contract `deliver-view` needs from the deployment beyond its handler.
pub trait DeliverViewHooks: Send + Sync + 'static + QuotaCounter {
    /// The payload of error `throttled` of contract `deliver-view` when quota `q-deliver-view` refuses a call, `retry_after` before the window ends.
    fn q_deliver_view_exceeded(&self, retry_after: std::time::Duration) -> types::ApiError;
}

/// Answers one call of contract `deliver-view`.
async fn answer_deliver_view<S: DeliverViewHandler, H: DeliverViewHooks>(
    handler: &S,
    hooks: &H,
    caller: strata_runtime::Caller,
    request: crate::contracts::DeliverViewRequest,
) -> Result<
    crate::contracts::DeliverViewResponse,
    strata_runtime::Failure<crate::contracts::DeliverViewError>,
> {
    let principal = principal(&caller);
    match hooks
        .count(&crate::quotas::Q_DELIVER_VIEW, &principal)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Unavailable, why))?
    {
        crate::quotas::QuotaOutcome::Allowed(_) => {}
        crate::quotas::QuotaOutcome::Exceeded { retry_after, .. } => {
            return Err(strata_runtime::Failure::Contract {
                error: crate::contracts::DeliverViewError::Throttled(
                    hooks.q_deliver_view_exceeded(retry_after),
                ),
            });
        }
    }
    handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

