/// What the route of contract `issue-submission-token` needs from the deployment beyond its handler.
pub trait IssueSubmissionTokenHooks: Send + Sync + 'static + QuotaCounter + QuotaWait {}

/// The route of contract `issue-submission-token` needs no hook of its own.
impl<T: Send + Sync + 'static + QuotaCounter + QuotaWait> IssueSubmissionTokenHooks for T {}

/// Answers one call of contract `issue-submission-token`.
async fn answer_issue_submission_token<
    S: IssueSubmissionTokenHandler,
    H: IssueSubmissionTokenHooks,
>(
    handler: &S,
    hooks: &H,
    caller: strata_runtime::Caller,
    request: crate::contracts::IssueSubmissionTokenRequest,
) -> Result<
    crate::contracts::IssueSubmissionTokenResponse,
    strata_runtime::Failure<crate::contracts::IssueSubmissionTokenError>,
> {
    let principal = principal(&caller);
    match hooks
        .count(&crate::quotas::Q_ISSUE_SUBMISSION_TOKEN, &principal)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Unavailable, why))?
    {
        crate::quotas::QuotaOutcome::Allowed(_) => {}
        crate::quotas::QuotaOutcome::Exceeded { retry_after, .. } => {
            hooks
                .wait(&crate::quotas::Q_ISSUE_SUBMISSION_TOKEN, retry_after)
                .await;
        }
    }
    handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

