/// What the route of contract `read-view` needs from the deployment beyond its handler.
pub trait ReadViewHooks: Send + Sync + 'static + QuotaCounter + QuotaWait {}

/// The route of contract `read-view` needs no hook of its own.
impl<T: Send + Sync + 'static + QuotaCounter + QuotaWait> ReadViewHooks for T {}

/// Answers one call of contract `read-view`.
async fn answer_read_view<S: ReadViewHandler, H: ReadViewHooks>(
    handler: &S,
    hooks: &H,
    caller: strata_runtime::Caller,
    request: crate::contracts::ReadViewRequest,
) -> Result<
    crate::contracts::ReadViewResponse,
    strata_runtime::Failure<crate::contracts::ReadViewError>,
> {
    let principal = principal(&caller);
    match hooks
        .count(&crate::quotas::Q_READ_VIEW, &principal)
        .await
        .map_err(|why| refusal(strata_runtime::FailureCode::Unavailable, why))?
    {
        crate::quotas::QuotaOutcome::Allowed(_) => {}
        crate::quotas::QuotaOutcome::Exceeded { retry_after, .. } => {
            hooks.wait(&crate::quotas::Q_READ_VIEW, retry_after).await;
        }
    }
    handler
        .handle(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

/// Adds the route of contract `read-view` to `routes`, answered by `handler` after the checks the specification states for it.
