/// Adds the route of every contract component `web-application` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn web_application_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::WebApplication + Send + Sync + 'static,
    H: WebApplicationHooks,
{
    let routes = serve_show_sign_in_page(routes, service.clone(), hooks.clone());
    let routes = serve_show_authoring_view(routes, service.clone(), hooks.clone());
    let routes = serve_save_draft(routes, service.clone(), hooks.clone());
    let routes = serve_show_review_diff(routes, service.clone(), hooks.clone());
    let routes = serve_preview_tokens(routes, service.clone(), hooks.clone());
    let routes = serve_show_status(routes, service.clone(), hooks.clone());
    let routes = serve_show_changelog(routes, service.clone(), hooks.clone());
    let routes = serve_show_service_objectives(routes, service.clone(), hooks.clone());
    serve_render_page(routes, service, hooks)
}

